const rows = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const seen = new Set();
return rows.filter(Boolean).map((row) => ({ ...row, telegram_user_id: String(row.telegram_user_id ?? row.telegramUserId ?? '') })).filter((row) => {
  if (!row.id || !/^[1-9][0-9]*$/.test(row.telegram_user_id) || !/^https?:\/\//.test(String(row.checkout_url ?? ''))) return false;
  const key = String(row.id);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).map((row) => ({ json: row }));

