const source = $input.first().json;
const envelope = source.body ?? source;
const type = String(envelope.type ?? envelope.event ?? '');
const data = envelope.data ?? {};
const critical = new Set(['order.created','order.dispatched','payment.verified','payment.rejected','payment.slip_uploaded','inventory.low_stock','ticket.created','ticket.resolved','purchase.received']);
if (!critical.has(type)) return [];
const labels = {'order.created':'New order','order.dispatched':'Order dispatched','payment.verified':'Payment verified','payment.rejected':'Payment rejected','payment.slip_uploaded':'Payment slip uploaded','inventory.low_stock':'Low stock warning','ticket.created':'New warranty ticket','ticket.resolved':'Warranty ticket resolved','purchase.received':'Purchase received'};
const target = String(data.targetCode ?? data.target_code ?? 'No reference');
const timestamp = String(envelope.timestamp ?? new Date().toISOString());
return [{ json: { event_key: `${type}:${target}:${timestamp}`, title: labels[type] ?? type, body: String(data.details ?? data.body ?? 'Open MH OP ERP for details.'), target_code: target, timestamp } }];

const rows = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const seen = new Set();
return rows.filter(Boolean).map((row) => ({ ...row, telegram_user_id: String(row.telegram_user_id ?? row.telegramUserId ?? '') })).filter((row) => {
  if (!/^[1-9][0-9]*$/.test(row.telegram_user_id) || !row.order_code || seen.has(row.telegram_user_id)) return false;
  seen.add(row.telegram_user_id);
  return true;
}).map((row) => ({ json: row }));
